const { ApolloServer, gql } = require('@apollo/server');
const { startStandaloneServer } = require('@apollo/server/standalone');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: 'appdb',
  user: process.env.DB_USER || 'app_service',
  password: process.env.DB_PASSWORD,
  max: 20,
  idleTimeoutMillis: 30000,
});

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    name: String!
    ssn: String
    salary: Float
    department: String
  }

  type Document {
    id: ID!
    title: String!
    content: String!
    ownerId: ID!
    classification: String!
  }

  type Query {
    me: User
    user(id: ID!): User
    document(id: ID!): Document
    myDocuments: [Document]
  }
`;

const resolvers = {
  Query: {
    me: async (_, __, context) => {
      if (!context.userId) throw new Error('Unauthorized');
      const result = await pool.query(
        'SELECT id, email, name, department FROM users WHERE id = $1',
        [context.userId]
      );
      return result.rows[0];
    },

    user: async (_, { id }, context) => {
      if (!context.userId) throw new Error('Unauthorized');
      // Fetches any user by ID - no authorization check against context.userId
      const result = await pool.query(
        'SELECT id, email, name, ssn, salary, department FROM users WHERE id = $1',
        [id]
      );
      return result.rows[0];
    },

    document: async (_, { id }, context) => {
      if (!context.userId) throw new Error('Unauthorized');
      // Direct object reference - fetches document without ownership check
      const result = await pool.query(
        'SELECT id, title, content, owner_id as "ownerId", classification FROM documents WHERE id = $1',
        [id]
      );
      return result.rows[0];
    },

    myDocuments: async (_, __, context) => {
      if (!context.userId) throw new Error('Unauthorized');
      const result = await pool.query(
        'SELECT id, title, content, owner_id as "ownerId", classification FROM documents WHERE owner_id = $1',
        [context.userId]
      );
      return result.rows;
    },
  },
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
});

async function start() {
  const { url } = await startStandaloneServer(server, {
    listen: { port: 4000 },
    context: async ({ req }) => {
      const token = req.headers.authorization?.replace('Bearer ', '');
      if (!token) return {};
      try {
        const jwt = require('jsonwebtoken');
        const decoded = jwt.verify(token, process.env.JWT_SECRET);
        return { userId: decoded.sub, role: decoded.role };
      } catch (e) {
        return {};
      }
    },
  });
  console.log(`Server ready at ${url}`);
}

start();
